arguments.command:
curl -s https://api.linear.app/graphql -H 'Content-Type: application/json' -H 'Authorization: Bearer <TOKEN>' -d '{"query":"{ issues(first: 200) { nodes { id project { id name team { key } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
seen={}
for n in d['data']['issues']['nodes']:
    p=n['project']
    if p:
        seen[p['name']]={'id':p['id'],'team':p['team']['key']}
print(json.dumps(seen,indent=1))
"

